import{_ as t,a0 as r,w as d,s as o,ao as p,I as n,x as a,a1 as i,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 CentOS 上使用 FirewallD 配置防火墙 | LCTT x X-CMD","titleTemplate":false,"description":"在 CentOS 上使用 FirewallD 配置防火墙 | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 CentOS 上使用 FirewallD 配置防火墙 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 CentOS 上使用 FirewallD 配置防火墙 | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7","title":"在 CentOS 上使用 FirewallD 配置防火墙","tag":"201705","desc":""},"relativePath":"201705/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7.md","filePath":"[post].md"}'),h={name:"201705/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7.md"};function c(g,s,m,f,u,b){const e=r("Link");return d(),o("div",null,[s[19]||(s[19]=p(`<h1 id="在-centos-上使用-firewalld-配置防火墙" tabindex="-1">在 CentOS 上使用 FirewallD 配置防火墙 <a class="header-anchor" href="#在-centos-上使用-firewalld-配置防火墙" aria-label="Permalink to “在 CentOS 上使用 FirewallD 配置防火墙”">​</a></h1><p><img src="https://www.rosehosting.com/blog/wp-content/uploads/2017/02/set-up-and-configure-a-firewall-with-firewalld-on-centos-7.jpg" alt=""></p><p>FirewallD 是 CentOS 7 服务器上默认使用的防火墙管理工具。从根本上来讲，它是在 iptables 基础上的一个包装，它同时拥有图形配置工具 firewall-config 和命令行工具 firewall-cmd。使用 iptables 服务的话，每次更改设置后都要求刷新旧的规则，然后从文件 <code>/etc/sysconfig/iptables</code> 中读取新的规则，然而 firewalld 只对差异进行改动。</p><h3 id="firewalld-区域" tabindex="-1">FirewallD 区域 <a class="header-anchor" href="#firewalld-区域" aria-label="Permalink to “FirewallD 区域”">​</a></h3><p>FirewallD 使用服务和区域代替 iptables 的规则和链。默认下面的区域都是可用的：</p><ul><li><p>drop——任何流入网络的包都被丢弃，不作出任何响应，只允许流出的网络连接。</p></li><li><p>block——任何进入的网络连接都被拒绝，并返回 IPv4 的 icmp-host-prohibited 报文。只允许流出的网络连接。</p></li><li><p>public——只接受选中的传入网络连接，例如在公共场合。</p></li><li><p>public——用于启用伪装的外部网络，只接受被选中的传入网络连接。</p></li><li><p>dmz——隔离区域(demilitarized zone),有限制地公开访问内部网络，只接受被选中的传入网络连接。</p></li><li><p>work——用于工作区域中的计算机，只接受选中的流入网络连接。</p></li><li><p>home——用于家庭区域中的计算机，只接受选中的流入网络连接。</p></li><li><p>internal——用于内部网络中的计算机，只接受选中的流入网络连接。</p></li><li><p>trusted——所有的网络连接都可以接受。</p></li></ul><p>要显示所有可用的区域可以运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-zones</span></span>
<span class="line"><span>work drop internal external trusted home dmz public block</span></span></code></pre></div><p>要显示默认的区域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>public</span></span></code></pre></div><p>改变默认的区域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --set-default-zone=dmz</span></span>
<span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>dmz</span></span></code></pre></div><h3 id="firewalld-服务" tabindex="-1">FirewallD 服务 <a class="header-anchor" href="#firewalld-服务" aria-label="Permalink to “FirewallD 服务”">​</a></h3><p>FirewallD服务是 xml 配置文件，每个文件里面记录有防火墙针对某项服务的配置信息。要列出所有可用的服务，运行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-services</span></span>
<span class="line"><span>amanda-client amanda-k5-client bacula bacula-client ceph ceph-mon dhcp dhcpv6 dhcpv6-client dns docker-registry dropbox-lansync freeipa-ldap freeipa-ldaps freeipa-replication ftp high-availability http https imap imaps ipp ipp-client ipsec iscsi-target kadmin kerberos kpasswd ldap ldaps libvirt libvirt-tls mdns mosh mountd ms-wbt mysql nfs ntp openvpn pmcd pmproxy pmwebapi pmwebapis pop3 pop3s postgresql privoxy proxy-dhcp ptp pulseaudio puppetmaster radius rpc-bind rsyncd samba samba-client sane smtp smtps snmp snmptrap squid ssh synergy syslog syslog-tls telnet tftp tftp-client tinc tor-socks transmission-client vdsm vnc-server wbem-https xmpp-bosh xmpp-client xmpp-local xmpp-server</span></span></code></pre></div><p>xml 配置文件存放在 <code>/usr/lib/firewalld/services/</code> 和 <code>/etc/firewalld/services/</code> 目录内。</p><h3 id="使用-firewalld-配置你的防火墙" tabindex="-1">使用 FirewallD 配置你的防火墙 <a class="header-anchor" href="#使用-firewalld-配置你的防火墙" aria-label="Permalink to “使用 FirewallD 配置你的防火墙”">​</a></h3>`,17)),n("p",null,[s[1]||(s[1]=a("作为一个例子，如果你正在运行一个 web 服务器、7022端口上的 SSH 和 mail 服务器，这里会告诉你如何用 FirewallD 配置你的 ",-1)),i(e,{href:"6"},{default:l(()=>[...s[0]||(s[0]=[a("RoseHosting VPS",-1)])]),_:1}),s[2]||(s[2]=a(" 防火墙。",-1))]),s[20]||(s[20]=p(`<p>我们首先设置默认区域为 dmz：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --set-default-zone=dmz</span></span>
<span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>dmz</span></span></code></pre></div><p>为了将 HTTP 和 HTTPS 的服务规则永久加入 dmz 区域，运行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --zone=dmz --add-service=http --permanent</span></span>
<span class="line"><span># firewall-cmd --zone=dmz --add-service=https --permanent</span></span></code></pre></div><p>打开 25 端口SMTP)和 465 端口(SMTPS):</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --zone=dmz --add-service=smtp --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=smtps --permanent</span></span></code></pre></div><p>打开 IMAP、IMAPS、POP3 和 POP3S端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --zone=dmz --add-service=imap --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=imaps --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=pop3 --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=pop3s --permanent</span></span></code></pre></div><p>因为 SSH 端口号已经被改为 7022，所以我们将删除 ssh 服务(端口 22)，然后开启端口 7022：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --remove-service=ssh --permanent </span></span>
<span class="line"><span>firewall-cmd --add-port=7022/tcp --permanent</span></span></code></pre></div><p>为了让这些改变生效，我们需要用命令重新加载防火墙：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --reload</span></span></code></pre></div><p>最后，你可以使用命令列出规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### firewall-cmd –list-all</span></span>
<span class="line"><span>dmz</span></span>
<span class="line"><span>target: default</span></span>
<span class="line"><span>icmp-block-inversion: no</span></span>
<span class="line"><span>interfaces:</span></span>
<span class="line"><span>sources:</span></span>
<span class="line"><span>services: http https imap imaps pop3 pop3s smtp smtps</span></span>
<span class="line"><span>ports: 7022/tcp</span></span>
<span class="line"><span>protocols:</span></span>
<span class="line"><span>masquerade: no</span></span>
<span class="line"><span>forward-ports:</span></span>
<span class="line"><span>sourceports:</span></span>
<span class="line"><span>icmp-blocks:</span></span>
<span class="line"><span>rich rules:</span></span></code></pre></div><hr>`,15)),n("p",null,[s[4]||(s[4]=a("当然，如果您使用我们的 ",-1)),i(e,{href:"https://www.rosehosting.com/centos-vps.html"},{default:l(()=>[...s[3]||(s[3]=[a("CentOS VPS hosting",-1)])]),_:1}),s[5]||(s[5]=a(" 服务中任何一种服务，您都不必亲自做上面任何设置，您可以让我们专业的 Linux 管理员来为您设置。他们提供 24x7 的服务，并且会立即处理您的要求。",-1))]),s[21]||(s[21]=n("p",null,"PS：如果您喜欢这篇文章，请将它分享到社交平台上与您的朋友共享，或者仅仅在下面留言回复。谢谢！",-1)),s[22]||(s[22]=n("hr",null,null,-1)),n("p",null,[s[7]||(s[7]=a("via: ",-1)),i(e,{href:"https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/"},{default:l(()=>[...s[6]||(s[6]=[a("https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=a("作者：",-1)),i(e,{href:"https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/"},{default:l(()=>[...s[8]||(s[8]=[a("rosehosting.com",-1)])]),_:1}),s[12]||(s[12]=a(" 译者：",-1)),i(e,{href:"https://github.com/zhousiyu325"},{default:l(()=>[...s[9]||(s[9]=[a("zhousiyu325",-1)])]),_:1}),s[13]||(s[13]=a(" 校对：",-1)),i(e,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:l(()=>[...s[10]||(s[10]=[a("校对者ID",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:l(()=>[...s[15]||(s[15]=[a("Linux中国",-1)])]),_:1}),s[18]||(s[18]=a(" 荣誉推出",-1))])])}const v=t(h,[["render",c]]);export{C as __pageData,v as default};
